FDN=["front_desk","night_audit"]; FDO=["front_desk"]; NAO=["night_audit"]
TIPS="https://www.ftc.gov/business-guidance/privacy-security"; IDT="https://consumer.ftc.gov/articles/what-know-about-identity-theft"
FEMA="https://www.ready.gov/power-outages"; RC="https://www.redcross.org/get-help/how-to-prepare-for-emergencies/types-of-emergencies/fire.html"
ELEV="https://www.osha.gov/elevators"; MAP="https://www.revisor.mn.gov/statutes/cite/327.72"
add(FDN,"role",[
("recovery","med","A guest's reservation can't be found at check-in. Best first step?","No encuentras la reservación del huésped al llegar. ¿Primer paso?",["Ask for the confirmation number and search by name, dates and third-party site","Tell them they don't have one","Send them to another hotel right away","Charge walk-in rate without checking"],["Pedir el número de confirmación y buscar por nombre, fechas y sitio externo","Decirle que no tiene","Mandarlo a otro hotel de inmediato","Cobrar tarifa de mostrador sin revisar"],"Most 'lost' reservations are under a different name, date or a third-party booking.","La mayoría están con otro nombre, fecha o en un sitio externo.",BP),
("recovery","hard","The hotel is oversold and you must 'walk' a guest with a confirmed reservation. What's standard good practice?","El hotel está sobrevendido y debes reubicar a un huésped con reservación. ¿Buena práctica?",["Apologize, book a comparable nearby hotel, cover the first night and transport","Tell them to find a room themselves","Put them in an out-of-order room","Ask them to wait in the lobby until a checkout"],["Disculparte, reservar un hotel cercano comparable, cubrir la primera noche y el transporte","Decirle que busque cuarto solo","Darle un cuarto fuera de servicio","Que espere en el lobby a que alguien salga"],"A courteous, paid relocation protects the guest and the hotel's reputation; follow your GM's walk procedure.","Una reubicación cortés y pagada protege al huésped y la reputación; sigue el procedimiento del gerente.",BP),
("recovery","easy","A guest's key card stops working. What should you do before making a new key?","La llave del huésped dejó de funcionar. ¿Qué haces antes de hacer otra?",["Verify their ID matches the guest on the room","Just make one","Ask what room they want","Give them a master key"],["Verificar que su ID coincida con el huésped del cuarto","Hacerla sin más","Preguntar qué cuarto quiere","Darle una llave maestra"],"Never issue a key without confirming identity — it protects every guest.","Nunca des una llave sin confirmar identidad; protege a todos.",BP),
("recovery","med","A guest finds the room wasn't what they booked (king vs. two queens). Best response?","El huésped encuentra un cuarto distinto al reservado (king vs. dos queen). ¿Mejor respuesta?",["Apologize, check availability and move them, or offer a fix if sold out","Say all rooms are the same","Tell them to call the booking site","Ignore it until tomorrow"],["Disculparte, revisar disponibilidad y cambiarlo, o una alternativa si no hay","Decir que todos son iguales","Que llame al sitio de reservas","Ignorarlo hasta mañana"],"Fix it now when possible; if not, offer what you can and log it for tomorrow.","Resuélvelo ahora si se puede; si no, ofrece algo y regístralo.",BP),
("recovery","med","Who should hear about a complaint you already fixed?","¿Quién debe saber de una queja que ya resolviste?",["Your manager and the next shift, through the log","Nobody — it's fixed","Only the guest","Social media"],["Tu gerente y el siguiente turno, por la bitácora","Nadie, ya está","Solo el huésped","Redes sociales"],"Logging lets others follow up and spot repeat problems.","Registrar permite dar seguimiento y ver problemas repetidos.",BP),
("upsell","med","When is the best time to mention a paid upgrade or late checkout?","¿Cuándo es mejor ofrecer una mejora pagada o salida tarde?",["During check-in, after greeting and confirming their stay","When they're rushing out","Only if they ask for a manager","By slipping a note under the door at night"],["En el check-in, tras saludar y confirmar la estancia","Cuando van de prisa","Solo si piden al gerente","Con una nota bajo la puerta en la noche"],"Check-in is the natural moment to match offers to the guest's needs.","El check-in es el momento natural para ofrecer según sus necesidades.",BP),
("upsell","easy","A guest booked through a third-party site. Which is a good, honest enrollment pitch?","Un huésped reservó por un sitio externo. ¿Qué invitación honesta es buena?",["Explain joining the hotel's loyalty program is free and book direct next time for member benefits","Say third-party bookings are illegal","Charge them a fee","Refuse to check them in"],["Explicar que el programa de lealtad es gratis y que la próxima reserve directo para beneficios","Decir que esas reservas son ilegales","Cobrarle una cuota","Negarle el check-in"],"Keep it positive; never criticize the guest's booking choice.","Mantenlo positivo; no critiques cómo reservó.",BP),
("reservations","med","A guest asks to cancel a non-refundable rate. What do you do?","Un huésped quiere cancelar una tarifa no reembolsable. ¿Qué haces?",["Explain the rate rules kindly and involve a manager for any exception","Refund it quietly","Tell them it's impossible and hang up","Change the rate type yourself"],["Explicar con amabilidad las reglas y pedir al gerente cualquier excepción","Reembolsar a escondidas","Decir que es imposible y colgar","Cambiar la tarifa tú mismo"],"Exceptions are a manager decision; explain the policy with empathy.","Las excepciones las decide el gerente; explica con empatía.",BP),
("reservations","easy","What should you read back before ending a reservation call?","¿Qué debes repetir antes de terminar una llamada de reservación?",["Name, dates, room type, rate, and cancellation policy","Only the hotel name","Your own schedule","Nothing"],["Nombre, fechas, tipo de cuarto, tarifa y política de cancelación","Solo el nombre del hotel","Tu horario","Nada"],"A read-back catches mistakes before arrival.","Repetir los datos evita errores al llegar.",BP),
("reservations","med","A group leader wants 10 rooms next month at a discount. What's the right move?","Un líder de grupo quiere 10 cuartos el mes que viene con descuento. ¿Qué haces?",["Take their details and pass it to the GM or sales for a group quote","Promise any rate they want","Block rooms without approval","Tell them groups aren't allowed"],["Tomar sus datos y pasarlo al gerente o ventas para cotizar","Prometer la tarifa que pida","Bloquear cuartos sin aprobación","Decir que no se aceptan grupos"],"Group rates and blocks need manager approval.","Las tarifas y bloqueos de grupo requieren aprobación.",BP),
("policy","med","Under Minnesota law, an innkeeper may remove a guest who:","Según la ley de Minnesota, el hotel puede sacar a un huésped que:",["Is disorderly or violates posted rules, after the steps the law requires","Complained about the Wi-Fi","Checked in late","Left a bad review"],["Es desordenado o viola las reglas publicadas, siguiendo los pasos de la ley","Se quejó del Wi-Fi","Llegó tarde","Dejó una mala reseña"],"Minn. Stat. 327.73 lists when a guest can be ejected; managers handle it.","La ley 327.73 indica cuándo; lo maneja el gerente.",INNK),
("policy","easy","A caller asks if their spouse is staying at the hotel. What do you say?","Alguien llama y pregunta si su esposo(a) está hospedado. ¿Qué dices?",["Don't confirm; offer to take a message or transfer without saying the room number","Give the room number","Confirm and describe them","Read the reservation details"],["No confirmar; ofrecer tomar un mensaje o transferir sin dar número","Dar el número de cuarto","Confirmar y describirlo","Leer la reservación"],"Guest privacy and safety come first — never confirm or give room numbers.","Primero la privacidad y seguridad: nunca confirmes ni des el número.",BP),
("policy","med","A guest asks to have a room key made for a visitor. Policy?","Un huésped pide una llave para un visitante. ¿Política?",["Only registered guests on the folio get keys; the guest can add the person per policy with ID","Make one for anyone they name","Give the visitor a master key","Leave the door propped"],["Solo huéspedes registrados reciben llave; puede agregarlo según la política con ID","Hacer para quien diga","Dar llave maestra al visitante","Dejar la puerta abierta"],"Keys go only to registered, identified guests.","Las llaves son solo para huéspedes registrados e identificados.",BP),
("cash","med","At shift change, how should two people hand off a cash drawer?","En el cambio de turno, ¿cómo se entrega una caja?",["Count it together and both sign the count","Leave it for the next person","Count it alone after they leave","Skip it when busy"],["Contarla juntos y firmar ambos","Dejarla para el siguiente","Contarla solo después","Omitirlo si hay mucho trabajo"],"A joint count makes each person accountable for their shift.","Contar juntos hace a cada uno responsable de su turno.",BP),
("cash","hard","A guest pays cash and wants change in large bills for a $100. Your drawer is short on 20s. Best action?","Un huésped paga en efectivo y quiere cambio de $100; te faltan billetes de 20. ¿Mejor acción?",["Follow your change-fund procedure with the manager — don't borrow from other funds","Take money from the bar drawer","Use tips","Give an IOU"],["Seguir el procedimiento de cambio con el gerente; no tomar de otros fondos","Tomar de la caja del bar","Usar propinas","Dar un vale"],"Mixing funds breaks accountability and causes variances.","Mezclar fondos rompe el control y causa diferencias.",BP),
("payments","med","A caller says they're from the card company and asks you to read a guest's card number. You:","Alguien dice ser de la compañía de tarjetas y pide el número de tarjeta de un huésped. Tú:",["Refuse and tell your manager — it's a common scam","Read it to them","Read only the last 8 digits","Email it"],["Negarte y avisar al gerente; es una estafa común","Leerlo","Leer los últimos 8 dígitos","Mandarlo por correo"],"Never share card data by phone; PCI rules protect it.","Nunca compartas datos de tarjetas por teléfono; PCI los protege.",PCI),
("payments","easy","Where may full card numbers be written down?","¿Dónde se pueden anotar números completos de tarjeta?",["Nowhere — only in the approved payment system","On a sticky note","In the shift log","On the reservation printout"],["En ningún lado; solo en el sistema de pago aprobado","En una nota adhesiva","En la bitácora","En la reservación impresa"],"PCI DSS bars storing card data outside secure systems.","PCI DSS prohibe guardar datos fuera de sistemas seguros.",PCI),
("security","med","Someone in the lobby asks you to let them into 'their friend's' room. You:","Alguien en el lobby pide que lo dejes entrar al cuarto de 'su amigo'. Tú:",["Politely refuse and offer to call the room","Let them in","Give a key if they know the room number","Ask housekeeping to open it"],["Negarte con cortesía y ofrecer llamar al cuarto","Dejarlo entrar","Dar llave si sabe el número","Pedir a limpieza que abra"],"Only registered guests get access.","Solo los huéspedes registrados tienen acceso.",BP),
("security","med","You notice a guest's door propped open late at night with nobody around. Best step?","Ves la puerta de un cuarto abierta tarde en la noche sin nadie. ¿Mejor paso?",["Call the room or knock and announce, and close it if no one answers, then log it","Walk in and look around","Ignore it","Take items for safekeeping"],["Llamar o tocar y anunciarte; cerrar si nadie responde y registrarlo","Entrar a revisar","Ignorarlo","Llevarte cosas para guardarlas"],"Protect the guest without entering the room; document it.","Protege al huésped sin entrar; regístralo.",BP),
("emergency","med","The power goes out at night. What's an early priority?","Se va la luz en la noche. ¿Una prioridad?",["Check elevators for trapped people and use flashlights, not candles","Light candles in the halls","Leave the desk to go home","Restart the PMS repeatedly"],["Revisar elevadores por personas atrapadas y usar linternas, no velas","Prender velas en pasillos","Irte a casa","Reiniciar el sistema una y otra vez"],"Ready.gov advises flashlights over candles; trapped riders need help first.","Ready.gov recomienda linternas en vez de velas.",FEMA),
("emergency","hard","The fire alarm sounds. Which is a front desk task?","Suena la alarma de incendio. ¿Tarea de recepción?",["Follow the fire plan: call 911/check the panel, grab the in-house list, guide guests out","Silence the alarm and wait","Use the elevator to check floors","Tell guests it's probably false"],["Seguir el plan: llamar al 911/revisar el panel, tomar la lista de huéspedes y guiarlos","Apagar la alarma y esperar","Usar el elevador para revisar","Decir que seguro es falsa"],"Never assume a false alarm; the in-house list helps account for guests.","Nunca supongas falsa alarma; la lista ayuda a ubicar huéspedes.",RC),
("checkout","easy","A guest disputes a charge on their bill at checkout. First step?","Un huésped disputa un cargo al salir. ¿Primer paso?",["Listen, review the folio with them, and correct or escalate per policy","Refuse to discuss","Remove every charge","Tell them to call their bank"],["Escuchar, revisar el folio juntos y corregir o escalar según política","Negarte a hablar","Quitar todos los cargos","Que llame a su banco"],"Calm review settles most disputes before a chargeback.","Revisar con calma resuelve la mayoría antes de un contracargo.",CB),
("phone","easy","You must put a caller on hold. What's polite?","Debes poner a alguien en espera. ¿Qué es cortés?",["Ask permission, say why, and check back quickly","Just press hold","Leave them for 10 minutes","Hang up and call back later"],["Pedir permiso, explicar y volver pronto","Solo poner en espera","Dejarlo 10 minutos","Colgar y llamar luego"],"Asking first and checking back keeps the caller's trust.","Pedir permiso y volver mantiene la confianza.",BP),
("language","easy","A guest speaks little English. What helps most?","Un huésped habla poco inglés. ¿Qué ayuda más?",["Speak slowly in simple words, use gestures or a translation app, and confirm understanding","Talk louder","Hand them a long printed policy","Rush through check-in"],["Hablar despacio y simple, usar gestos o una app y confirmar que entendió","Hablar más fuerte","Darle una política larga impresa","Apurar el check-in"],"Simple language and tools beat volume.","Palabras simples y herramientas sirven más que gritar.",BP),
])
add(NAO,"role",[
("audit","med","What's the main goal of the night audit?","¿Objetivo principal de la auditoría nocturna?",["Post the day's room and tax charges and verify the day's revenue balances","Clean the lobby","Plan next month's schedule","Approve payroll"],["Cargar cuartos e impuestos del día y verificar que cuadren los ingresos","Limpiar el lobby","Planear el próximo mes","Aprobar nómina"],"The audit closes the business day so records balance.","La auditoría cierra el día para que todo cuadre.",BP),
("audit","med","A reservation is still 'arriving' at audit time. What should you check before marking it a no-show?","Una reservación sigue 'por llegar' en la auditoría. ¿Qué revisas antes del no-show?",["Guarantee type, any late-arrival note, and the hotel's no-show policy","Nothing — cancel it","Whether it's raining","The guest's social media"],["Tipo de garantía, notas de llegada tarde y la política de no-show","Nada, cancelarla","Si llueve","Sus redes sociales"],"Checking avoids charging guests who are just late.","Revisar evita cobrar a quien solo viene tarde.",BP),
("audit","hard","Rooms sold 80, rooms available 100, room revenue $8,000. What's RevPAR?","Vendidos 80, disponibles 100, ingreso $8,000. ¿RevPAR?",["$80","$100","$64","$8,000"],["$80","$100","$64","$8,000"],"RevPAR = room revenue ÷ rooms available = 8,000 ÷ 100.","RevPAR = ingreso ÷ cuartos disponibles = 8,000 ÷ 100.",BP),
("audit","med","Housekeeping shows a room vacant but the system shows it occupied. This is called a:","Limpieza dice vacío pero el sistema dice ocupado. Esto se llama:",["Room status discrepancy — investigate before audit closes","Upgrade","Comp","Overbook"],["Discrepancia de estatus; investigar antes de cerrar","Mejora","Cortesía","Sobreventa"],"Discrepancies can hide skips or sleepers.","Las discrepancias pueden ocultar fugas o cuartos sin cobrar.",BP),
("audit","med","Before you run the end-of-day close, what should you print or save?","Antes de cerrar el día, ¿qué imprimes o guardas?",["Required reports such as the in-house list and arrivals in case the system goes down","Nothing","Only the weather","A guest's card numbers"],["Reportes requeridos como lista de huéspedes y llegadas por si falla el sistema","Nada","Solo el clima","Números de tarjetas"],"Backup lists let you work if the PMS fails.","Las listas de respaldo sirven si falla el sistema.",BP),
("security","med","At 3 a.m. a person with no key wanders the halls. Best response?","A las 3 a.m. alguien sin llave camina por los pasillos. ¿Mejor respuesta?",["Politely ask if you can help, verify they're a guest, and call police if they're a threat","Ignore them","Confront them aggressively","Lock yourself in the office and wait"],["Preguntar con cortesía si puede ayudarle, verificar si es huésped y llamar a la policía si es amenaza","Ignorarlo","Enfrentarlo agresivamente","Encerrarte y esperar"],"Friendly contact deters problems; call for help when needed.","El contacto amable previene problemas; pide ayuda si hace falta.",BP),
("security","easy","Working alone overnight, how often should someone know you're OK?","Trabajando solo de noche, ¿alguien debe saber que estás bien?",["Follow the hotel's check-in plan and keep a phone with you","Never","Only if you get hurt","Once a month"],["Seguir el plan de reporte del hotel y tener un teléfono","Nunca","Solo si te lastimas","Una vez al mes"],"Lone-worker check-ins get help fast if something happens.","Reportarse ayuda a que llegue ayuda rápido.",BP),
])
